-- Audit completeness (spec 27). The audit trigger covered 23 tables; these were added later or were missed.
-- Prices and ward rates change what patients are billed, logins show who was in the system, and reminders show
-- what was sent. notifications and expiry_alerts_sent are left out on purpose: they are system-generated by-products
-- of events that are already audited.

do $$
declare t text;
begin
  foreach t in array array['wards', 'services', 'staff_sessions', 'reminders'] loop
    execute format('create trigger audit_%1$s after insert or update or delete on %1$I for each row execute function audit_row()', t);
  end loop;
end $$;
